<?php
 namespace Pterodactyl\Services\Dezerx\Minecraft; use Illuminate\Support\Facades\Storage; class RegionFile { private const HEADER_BYTES = 8192; private const SECTOR = 4096; private const DISK = 'local'; private const DIRECTORY = 'dezerx/world-cache'; private const TTL_MINUTES = 15; private const MAX_BYTES = 64_000_000; public static function fetch(ServerFiles $files, string $server, string $path): ?string { self::prune(); $key = self::key($server, $path).'.mca'; $disk = Storage::disk(self::DISK); if ($disk->exists($key) && $disk->lastModified($key) > time() - (self::TTL_MINUTES * 60)) { return $disk->path($key); } $raw = $files->fileContents($path, self::MAX_BYTES); if ($raw === null || strlen($raw) < self::HEADER_BYTES) { return null; } $disk->put($key, $raw); return $disk->path($key); } public static function tilePath(string $server, string $path): string { $disk = Storage::disk(self::DISK); if (!$disk->directoryExists(self::DIRECTORY)) { $disk->makeDirectory(self::DIRECTORY); } return $disk->path(self::key($server, $path).'.png'); } public static function index(string $file): ?array { $handle = @fopen($file, 'rb'); if ($handle === false) { return null; } $header = fread($handle, self::HEADER_BYTES); fclose($handle); if ($header === false || strlen($header) < self::HEADER_BYTES) { return null; } $chunks = []; for ($i = 0; $i < 1024; $i++) { $entry = substr($header, $i * 4, 4); $offset = (ord($entry[0]) << 16) | (ord($entry[1]) << 8) | ord($entry[2]); $sectors = ord($entry[3]); if ($offset === 0 || $sectors === 0) { continue; } $timestamp = unpack('N', substr($header, 4096 + ($i * 4), 4))[1] ?? 0; $chunks[] = [ 'index' => $i, 'x' => $i % 32, 'z' => intdiv($i, 32), 'offset' => $offset, 'sectors' => $sectors, 'bytes' => $sectors * self::SECTOR, 'modifiedAt' => $timestamp > 0 ? date(DATE_ATOM, $timestamp) : null, ]; } return $chunks; } public static function chunk(string $file, int $offset, int $sectors): ?array { $handle = @fopen($file, 'rb'); if ($handle === false) { return null; } fseek($handle, $offset * self::SECTOR); $raw = fread($handle, $sectors * self::SECTOR); fclose($handle); if ($raw === false || strlen($raw) < 5) { return null; } $length = unpack('N', substr($raw, 0, 4))[1] ?? 0; $scheme = ord($raw[4]); $body = substr($raw, 5, max(0, $length - 1)); return match ($scheme) { 1 => [(string) gzdecode($body), Nbt::GZIP], 2 => [(string) zlib_decode($body), Nbt::ZLIB], 3 => [$body, Nbt::RAW], default => null, }; } public static function deleteChunks(string $file, array $indexes): bool { $handle = @fopen($file, 'r+b'); if ($handle === false) { return false; } foreach ($indexes as $index) { $index = (int) $index; if ($index < 0 || $index > 1023) { continue; } fseek($handle, $index * 4); fwrite($handle, "\x00\x00\x00\x00"); } fclose($handle); return true; } public static function forget(string $server): void { $disk = Storage::disk(self::DISK); if (!$disk->directoryExists(self::DIRECTORY)) { return; } foreach ($disk->files(self::DIRECTORY) as $file) { if (str_starts_with(basename($file), $server.'-')) { $disk->delete($file); } } } private static function key(string $server, string $path): string { return self::DIRECTORY.'/'.$server.'-'.sha1($path); } private static function prune(): void { $disk = Storage::disk(self::DISK); if (!$disk->directoryExists(self::DIRECTORY)) { $disk->makeDirectory(self::DIRECTORY); return; } $cutoff = time() - (self::TTL_MINUTES * 60); foreach ($disk->files(self::DIRECTORY) as $file) { $limit = str_ends_with($file, '.png') ? $cutoff - (45 * 60) : $cutoff; if ($disk->lastModified($file) < $limit) { $disk->delete($file); } } } } 